SELECT T.CHECK_NO, T.BASIC_NO, T.TEA_EMPID, T.TEA_LOCAL_NAME, (SELECT GET_DEPT_NAME(H.DEPTNO, #{lang, jdbcType=VARCHAR}) FROM HR_EMPLOYEE H WHERE H.EMPID = T.TEA_EMPID AND ROWNUM = 1) AS TEA_DEPT_NAME, (SELECT GET_GLOBAL_NAME(H.POST_GRADE_NO, #{lang, jdbcType=VARCHAR}) FROM HR_EMPLOYEE H WHERE H.EMPID = T.TEA_EMPID AND ROWNUM = 1) AS TEA_POST_GRADE_NAME, T.STU_EMPID, T.STU_LOCAL_NAME, T.GROOMING, T.ALLSCORE, T.OTHER_ADVISE FROM EDU_TEACHER_CHECK T WHERE T.BASIC_NO = #{basicNo, jdbcType=NUMERIC} AND T.ACTIVITY = 1 AND T.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
AND T.TEA_EMPID = #{teaEmpid, jdbcType=VARCHAR}
ORDER BY T.TEA_EMPID, T.STU_EMPID

